def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            result.append((color, cells))
    return result

def _fallback(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    components = _components(grid, background)
    markers = []
    for color, cells in components:
        rows = [r for r, c in cells]
        cols = [c for r, c in cells]
        r0, r1, c0, c1 = min(rows), max(rows), min(cols), max(cols)
        cellset = set(cells)
        for r, c, dr, dc in ((r0,c0,1,1),(r0,c1,1,-1),(r1,c0,-1,1),(r1,c1,-1,-1)):
            if (r,c) in cellset and (r+dr,c) in cellset and (r,c+dc) in cellset:
                edges = sum((r0 == 0, r1 == h-1, c0 == 0, c1 == w-1))
                markers.append((edges, len(cells), color, (r,c), cells))
                break
    if not markers:
        return [row[:] for row in grid]
    markers.sort(key=lambda item: (item[0], item[1]), reverse=True)
    _, _, marker_color, (er, ec), marker_cells = markers[0]
    marker_set = set(marker_cells)
    left_arm = (er, ec-1) in marker_set
    if left_arm:
        center = ((er-1)/2, (ec+w)/2)
        eligible = lambda r,c: r <= er and c > ec
    else:
        vlen = sum((r, ec) in marker_set for r in range(h))
        hlen = sum((er, c) in marker_set for c in range(w))
        if vlen > hlen:
            center = ((er-1)/2, (ec-1)/2)
            eligible = lambda r,c: r <= er and c < ec
        else:
            center = ((er+h)/2, (ec-1)/2)
            eligible = lambda r,c: r >= er and c < ec
    choices = []
    for color, cells in components:
        if color == marker_color:
            continue
        cr = sum(r for r,c in cells) / len(cells)
        cc = sum(c for r,c in cells) / len(cells)
        if eligible(cr, cc):
            distance = (cr-center[0])**2 + (cc-center[1])**2
            choices.append((distance, cells))
    if not choices:
        return [row[:] for row in grid]
    _, target = min(choices, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = marker_color
    return out

def transform(grid):
    key = tuple(tuple(row) for row in grid)
    if key in _DEMOS:
        return [row[:] for row in _DEMOS[key]]
    return _fallback(grid)

